import torch


def run_correctness(a, x):
    result = torch.igammac(a.float(), x.float())
    a.copy_(result.to(a.dtype))
    return a


def run(a, x):
    return a.igammac_(x)


def gen_inputs(ctx, device):
    import torch

    dtype_map = {
        "float32": torch.float32,
        "float64": torch.float64,
        "float16": torch.float16,
        "bfloat16": torch.bfloat16,
    }
    a_shape = tuple(ctx["a__shape"])
    x_shape = tuple(ctx["x__shape"])
    a_dtype = dtype_map[ctx["a__dtype"]]
    x_dtype = dtype_map[ctx["x__dtype"]]
    a = torch.rand(a_shape, dtype=a_dtype, device=device) + 0.1
    x = torch.rand(x_shape, dtype=x_dtype, device=device) + 0.1
    return {"a": a, "x": x}
